require __DIR__.'/../includes/functions.php'; require_login('admin'); $error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$title=trim($_POST['title']??'');if($title==='')$error='عنوان سال تحصیلی را وارد کنید.';else{db()->prepare('UPDATE academic_years SET is_active=0')->execute();db()->prepare('INSERT INTO academic_years(title,is_active) VALUES(?,1) ON DUPLICATE KEY UPDATE is_active=1')->execute([$title]);audit('year_created','academic_year');flash('سال تحصیلی فعال شد.');redirect('/admin/years.php');}}
$years=db()->query('SELECT y.*,COUNT(e.id) students FROM academic_years y LEFT JOIN student_enrollments e ON e.academic_year_id=y.id GROUP BY y.id ORDER BY y.created_at DESC');layout_start('سال‌های تحصیلی');?><div class="page-head"><div><p class="eyebrow">مدیریت ساختار</p><h1>سال‌های تحصیلی</h1></div><a class="button secondary" href="<?=e(url('/admin/index.php'))?>">بازگشت</a></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="card"><h2>فعال‌سازی سال تحصیلی</h2><form class="form-grid" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>عنوان، مانند ۱۴۰۵–۱۴۰۶<input name="title" required></label><button class="button">فعال‌سازی</button></form></div><div class="card table-wrap"><table><thead><tr><th>عنوان</th><th>وضعیت</th><th>ثبت‌نام‌ها</th><th>ایجاد</th></tr></thead><tbody><?php while($y=$years->fetch()):?><tr><td><?=e($y['title'])?></td><td><?= $y['is_active']?'فعال':'بایگانی'?></td><td><?=e($y['students'])?></td><td><?=e($y['created_at'])?></td></tr><?php endwhile;?></tbody></table></div><?php layout_end(); ?>
